import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const Navigation = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { path: '/profile', label: 'Profile' },
    { path: '/upload', label: 'Upload Bill' },
    { path: '/budget', label: 'Trip Budget' },
    { path: '/team-bills', label: 'Team Bills' },
  ];

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  return (
    <nav className="navbar">
      <div className="navbar-brand" onClick={() => navigate('/upload')}>AI Expense Manager</div>
      <div className="nav-actions">
        {navItems.map((item) => {
          const isActive = location.pathname === item.path;
          return (
            <button
              key={item.path}
              type="button"
              className={`nav-link ${isActive ? 'active' : ''}`}
              onClick={() => navigate(item.path)}
            >
              {item.label}
            </button>
          );
        })}
        <button type="button" className="nav-link danger" onClick={handleLogout}>Logout</button>
      </div>
    </nav>
  );
};

export default Navigation;
